foundation.question_text:
Prove that $\Delta ABD \equiv \Delta CDB$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.95]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tickmark2/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2pt,-4pt)--(-2pt,4pt);\draw (2pt,-4pt)--(2pt,4pt);}}}}}
\coordinate (A) at (0,2);
\coordinate (B) at (3.4,2);
\coordinate (C) at (4.2,0);
\coordinate (D) at (0.8,0);
\draw[tickmark2] (A) -- (B);
\draw[tickmark] (B) -- (C);
\draw[tickmark2] (D) -- (C);
\draw[tickmark] (A) -- (D);
\draw (B) -- (D);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[below left] at (D) {$D$};
\end{tikzpicture}
[/tikz]

Prove that $\Delta ABC \equiv \Delta ADC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (A) at (0,0);
\coordinate (B) at (0.714,1.532);
\coordinate (C) at (4,0);
\coordinate (D) at (0.714,-1.532);
\draw[tickmark] (A) -- (B);
\draw (B) -- (C);
\draw (C) -- (D);
\draw[tickmark] (A) -- (D);
\draw (A) -- (C);
\pic[draw,angle radius=0.7cm] {angle=C--A--B};
\pic[draw,angle radius=0.55cm] {angle=D--A--C};
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[right] at (C) {$C$};
\node[below] at (D) {$D$};
\end{tikzpicture}
[/tikz]

Prove that $\Delta ABC \equiv \Delta EDC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.95]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tickmark2/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2pt,-4pt)--(-2pt,4pt);\draw (2pt,-4pt)--(2pt,4pt);}}}}}
\coordinate (C) at (0,0);
\coordinate (A) at (-2.3,0.8);
\coordinate (E) at (2.3,-0.8);
\coordinate (B) at (-1.9,-1.2);
\coordinate (D) at (1.9,1.2);
\draw[tickmark] (A) -- (C);
\draw[tickmark] (C) -- (E);
\draw[tickmark2] (B) -- (C);
\draw[tickmark2] (C) -- (D);
\draw (A) -- (B);
\draw (E) -- (D);
\node[above left] at (A) {$A$};
\node[below left] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[above right] at (D) {$D$};
\node[below right] at (E) {$E$};
\end{tikzpicture}
[/tikz]

Prove that $\Delta ABC \equiv \Delta ADC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\usetikzlibrary{calc}
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (A) at (0,0);
\coordinate (B) at (0.714,1.532);
\coordinate (C) at (4,0);
\coordinate (D) at (0.714,-1.532);
\draw[tickmark] (A) -- (B);
\draw (B) -- (C);
\draw (C) -- (D);
\draw[tickmark] (A) -- (D);
\draw (A) -- (C);
\coordinate (b1) at ($(B)!0.3cm!(A)$);
\coordinate (b2) at ($(B)!0.3cm!(C)$);
\draw (b1) -- ($(b1)+(b2)-(B)$) -- (b2);
\coordinate (d1) at ($(D)!0.3cm!(A)$);
\coordinate (d2) at ($(D)!0.3cm!(C)$);
\draw (d1) -- ($(d1)+(d2)-(D)$) -- (d2);
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[right] at (C) {$C$};
\node[below] at (D) {$D$};
\end{tikzpicture}
[/tikz]

$O$ is the centre of the circle. Prove that $\Delta OAB \equiv \Delta OCB$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (O) at (0,0);
\coordinate (A) at (1.147,1.638);
\coordinate (C) at (1.147,-1.638);
\coordinate (B) at (3.4,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt);
\draw (O) -- (A);
\draw (O) -- (C);
\draw (O) -- (B);
\draw[tickmark] (A) -- (B);
\draw[tickmark] (C) -- (B);
\node[left] at (O) {$O$};
\node[above] at (A) {$A$};
\node[right] at (B) {$B$};
\node[below] at (C) {$C$};
\end{tikzpicture}
[/tikz]

In the diagram $AB \parallel DE$. Prove that $\Delta ABC \equiv \Delta EDC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.95]
\usetikzlibrary{calc}
\tikzset{tickmark2/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2pt,-4pt)--(-2pt,4pt);\draw (2pt,-4pt)--(2pt,4pt);}}}}}
\coordinate (C) at (0,0);
\coordinate (A) at (-2.2,1.0);
\coordinate (E) at (2.2,-1.0);
\coordinate (B) at (-2.0,-1.1);
\coordinate (D) at (2.0,1.1);
\draw (A) -- (C) -- (E);
\draw[tickmark2] (B) -- (C);
\draw[tickmark2] (C) -- (D);
\draw (A) -- (B);
\draw (D) -- (E);
\draw[->] ($(A)!0.42!(B)$) -- ($(A)!0.58!(B)$);
\draw[->] ($(D)!0.42!(E)$) -- ($(D)!0.58!(E)$);
\node[above left] at (A) {$A$};
\node[below left] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[above right] at (D) {$D$};
\node[below right] at (E) {$E$};
\end{tikzpicture}
[/tikz]

In the diagram $A$, $D$ and $C$ lie on a straight line and $\angle ADB = \angle CDB = 90^{\circ}$. Prove that $\Delta ABD \equiv \Delta CBD$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\usetikzlibrary{calc}
\coordinate (A) at (-2,0);
\coordinate (C) at (2,0);
\coordinate (D) at (0,0);
\coordinate (B) at (0,2.6);
\draw (A) -- (C);
\draw (B) -- (D);
\draw (A) -- (B);
\draw (C) -- (B);
\coordinate (d1) at ($(D)!0.3cm!(A)$);
\coordinate (d2) at ($(D)!0.3cm!(B)$);
\draw (d1) -- ($(d1)+(d2)-(D)$) -- (d2);
\coordinate (d3) at ($(D)!0.3cm!(C)$);
\draw (d3) -- ($(d3)+(d2)-(D)$) -- (d2);
\pic[draw,angle radius=0.6cm] {angle=A--B--D};
\pic[draw,angle radius=0.6cm] {angle=D--B--C};
\node[below left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[below] at (D) {$D$};
\end{tikzpicture}
[/tikz]

development.question_text:
$O$ is the centre of the circle. Prove that $\Delta AOB \equiv \Delta DOC$, and hence that $AB \parallel CD$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\coordinate (O) at (0,0);
\coordinate (A) at (-1.879,0.684);
\coordinate (D) at (1.879,-0.684);
\coordinate (B) at (-0.347,1.970);
\coordinate (C) at (0.347,-1.970);
\draw (O) circle (2);
\fill (O) circle (1.5pt);
\draw (A) -- (D);
\draw (B) -- (C);
\draw (A) -- (B);
\draw (D) -- (C);
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[below] at (C) {$C$};
\node[right] at (D) {$D$};
\node[below right] at (O) {$O$};
\end{tikzpicture}
[/tikz]

$PQ = PR$ and $PS \perp QR$. Prove that $\Delta PSQ \equiv \Delta PSR$, and hence that $S$ is the midpoint of $QR$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\usetikzlibrary{calc}
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (P) at (0,3);
\coordinate (Q) at (-2,0);
\coordinate (R) at (2,0);
\coordinate (S) at (0,0);
\draw[tickmark] (P) -- (Q);
\draw[tickmark] (P) -- (R);
\draw (Q) -- (R);
\draw (P) -- (S);
\coordinate (s1) at ($(S)!0.3cm!(R)$);
\coordinate (s2) at ($(S)!0.3cm!(P)$);
\draw (s1) -- ($(s1)+(s2)-(S)$) -- (s2);
\node[above] at (P) {$P$};
\node[below left] at (Q) {$Q$};
\node[below right] at (R) {$R$};
\node[below] at (S) {$S$};
\end{tikzpicture}
[/tikz]

$AC$ and $DB$ meet at $E$, with $AE = CE$ and $DE = BE$. Prove that $\Delta AED \equiv \Delta CEB$, and hence that $\angle A = \angle C$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.95]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tickmark2/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2pt,-4pt)--(-2pt,4pt);\draw (2pt,-4pt)--(2pt,4pt);}}}}}
\coordinate (E) at (0,0);
\coordinate (A) at (-2.2,0.9);
\coordinate (C) at (2.2,-0.9);
\coordinate (D) at (-1.6,-1.3);
\coordinate (B) at (1.6,1.3);
\draw[tickmark] (A) -- (E);
\draw[tickmark] (E) -- (C);
\draw[tickmark2] (D) -- (E);
\draw[tickmark2] (E) -- (B);
\draw (A) -- (D);
\draw (C) -- (B);
\node[above left] at (A) {$A$};
\node[below right] at (C) {$C$};
\node[below left] at (D) {$D$};
\node[above right] at (B) {$B$};
\node[above right] at (E) {$E$};
\end{tikzpicture}
[/tikz]

$A$, $B$ and $C$ lie on a straight line, $DA = DC$ and $\angle ADB = \angle CDB$. Prove that $\Delta ABD \equiv \Delta CBD$, and hence that $AC \perp BD$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (A) at (-2,0);
\coordinate (B) at (0,0);
\coordinate (C) at (2,0);
\coordinate (D) at (0,2.6);
\draw (A) -- (C);
\draw (D) -- (B);
\draw[tickmark] (D) -- (A);
\draw[tickmark] (D) -- (C);
\pic[draw,angle radius=0.6cm] {angle=A--D--B};
\pic[draw,angle radius=0.6cm] {angle=B--D--C};
\node[below left] at (A) {$A$};
\node[below] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[above] at (D) {$D$};
\end{tikzpicture}
[/tikz]

Prove that $\Delta ABD \equiv \Delta CDB$, and hence that $AD \parallel BC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tickmark2/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2pt,-4pt)--(-2pt,4pt);\draw (2pt,-4pt)--(2pt,4pt);}}}}}
\coordinate (A) at (0,2.2);
\coordinate (B) at (3.0,2.2);
\coordinate (C) at (4.0,0);
\coordinate (D) at (1.0,0);
\draw[tickmark2] (A) -- (B);
\draw[tickmark] (B) -- (C);
\draw[tickmark2] (D) -- (C);
\draw[tickmark] (A) -- (D);
\draw (B) -- (D);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[below left] at (D) {$D$};
\end{tikzpicture}
[/tikz]

$AB = AD$ and $\angle ABC = \angle ADC = 90^{\circ}$. Prove that $\Delta ABC \equiv \Delta ADC$, and hence that $AC$ bisects $\angle BAD$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\usetikzlibrary{calc}
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (A) at (0,0);
\coordinate (B) at (0.938,1.802);
\coordinate (C) at (4.4,0);
\coordinate (D) at (0.938,-1.802);
\draw[tickmark] (A) -- (B);
\draw (B) -- (C);
\draw (C) -- (D);
\draw[tickmark] (A) -- (D);
\draw (A) -- (C);
\coordinate (b1) at ($(B)!0.3cm!(A)$);
\coordinate (b2) at ($(B)!0.3cm!(C)$);
\draw (b1) -- ($(b1)+(b2)-(B)$) -- (b2);
\coordinate (e1) at ($(D)!0.3cm!(A)$);
\coordinate (e2) at ($(D)!0.3cm!(C)$);
\draw (e1) -- ($(e1)+(e2)-(D)$) -- (e2);
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[right] at (C) {$C$};
\node[below] at (D) {$D$};
\end{tikzpicture}
[/tikz]

mastery.question_text:
$O$ is the centre of the circle, $D$ lies on the chord $AB$ with $AD = BD$, and $O$, $D$, $C$ are collinear. Use congruent triangles to prove that $OC \perp AB$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (O) at (0,2.4);
\coordinate (A) at (-2,0);
\coordinate (B) at (2,0);
\coordinate (D) at (0,0);
\coordinate (C) at (0,-0.724);
\draw (O) circle (3.124);
\fill (O) circle (1.5pt);
\draw (A) -- (B);
\draw (O) -- (C);
\draw (O) -- (A);
\draw (O) -- (B);
\draw[tickmark] (A) -- (D);
\draw[tickmark] (D) -- (B);
\node[above] at (O) {$O$};
\node[left] at (A) {$A$};
\node[right] at (B) {$B$};
\node[above right] at (D) {$D$};
\node[below] at (C) {$C$};
\end{tikzpicture}
[/tikz]

$A$, $B$ and $C$ lie on a straight line through $B$, with $\angle ABD = \angle CBD = 90^{\circ}$ and $\angle ADB = \angle CDB$. Prove that $\Delta ABD \equiv \Delta CBD$, and hence that $\Delta ACD$ is isosceles.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\usetikzlibrary{calc}
\coordinate (A) at (-2,2.4);
\coordinate (B) at (0,2.4);
\coordinate (C) at (2,2.4);
\coordinate (D) at (0,0);
\draw (A) -- (C);
\draw (B) -- (D);
\draw (A) -- (D);
\draw (C) -- (D);
\coordinate (b1) at ($(B)!0.3cm!(A)$);
\coordinate (b2) at ($(B)!0.3cm!(D)$);
\draw (b1) -- ($(b1)+(b2)-(B)$) -- (b2);
\coordinate (b3) at ($(B)!0.3cm!(C)$);
\draw (b3) -- ($(b3)+(b2)-(B)$) -- (b2);
\pic[draw,angle radius=0.6cm] {angle=B--D--A};
\pic[draw,angle radius=0.6cm] {angle=C--D--B};
\node[above left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[below] at (D) {$D$};
\end{tikzpicture}
[/tikz]

$A$, $D$ and $C$ lie on a straight line, and $B$ is joined to $A$, $C$ and $D$. $AB = CB$ and $\angle ABD = \angle CBD$. Prove that $\Delta ABD \equiv \Delta CBD$, and hence that $BD \perp AC$ and $D$ is the midpoint of $AC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\tikzset{tickmark/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}}}
\coordinate (B) at (0,2.8);
\coordinate (A) at (-2,0);
\coordinate (C) at (2,0);
\coordinate (D) at (0,0);
\draw (A) -- (C);
\draw (B) -- (D);
\draw[tickmark] (B) -- (A);
\draw[tickmark] (B) -- (C);
\pic[draw,angle radius=0.55cm] {angle=A--B--D};
\pic[draw,angle radius=0.55cm] {angle=D--B--C};
\node[above] at (B) {$B$};
\node[below left] at (A) {$A$};
\node[below right] at (C) {$C$};
\node[below] at (D) {$D$};
\end{tikzpicture}
[/tikz]
